    if (notepadContext) {
      messages.push(`<session-restore>

[NOTEPAD PRIORITY CONTEXT LOADED]

${notepadContext}

</session-restore>

---
`);
    }

    // Load root AGENTS.md if it exists (deepinit output - issue #613)
    // Skip when a generated CLAUDE.md exists — Claude Code loads it as claudeMd automatically
    const agentsMdPath = join(directory, 'AGENTS.md');
    const claudeMdPath = join(directory, 'CLAUDE.md');
    let skipAgentsMd = false;
    if (existsSync(claudeMdPath)) {
      try {
        const head = readFileSync(claudeMdPath, 'utf-8').slice(0, 200);
        if (head.includes('Generated from `AGENTS.md`')) {
          skipAgentsMd = true;
        }
      } catch {
        // Fall through to load AGENTS.md
      }
    }
    if (!skipAgentsMd && existsSync(agentsMdPath)) {
      try {
        const agentsContent = compactOmcStartupGuidance(readFileSync(agentsMdPath, 'utf-8').trim());
        if (agentsContent) {
          messages.push(`<session-restore>

[ROOT AGENTS.md LOADED]

The following project documentation was generated by deepinit to help AI agents understand the codebase:

${agentsContent}

</session-restore>

---
`);
        }
      } catch {
        // Skip if file can't be read
      }
    }

    if (messages.length > 0 || userMessages.length > 0) {
      const output = {
        continue: true,
      };
      if (userMessages.length > 0) {
        output.systemMessage = userMessages.join('\n');
      }
      if (messages.length > 0) {
        output.hookSpecificOutput = {
          hookEventName: 'SessionStart',
          additionalContext: buildSessionStartAdditionalContext(messages)
        };
      }
      console.log(JSON.stringify(output));
    } else {
      console.log(JSON.stringify({ continue: true, suppressOutput: true }));
    }
  } catch (error) {
    console.log(JSON.stringify({ continue: true, suppressOutput: true }));
  }
}

